from src.exceptions import InvalidReservationError
from src.reservations import reserve, cancel, get_available

with tempfile.TemporaryDirectory() as d:
    path = os.path.join(d, 'check.db')
    init_db(path)
    seed_inventory(path, {'A': 4, 'B': 4})
    reserve(path, 'r1', 'A', 2)
    assert reserve(path, 'r1', 'A', 2)['status'] == 'active'
    assert get_available(path, 'A') == 2
    for args in [('B', 2), ('A', 1)]:
        try:
            reserve(path, 'r1', *args)
        except InvalidReservationError:
            pass
        else:
            raise AssertionError('conflicting replay accepted')
    assert get_available(path, 'A') == 2 and get_available(path, 'B') == 4
    cancel(path, 'r1')
    cancel(path, 'r1')
    try:
        reserve(path, 'r1', 'A', 2)
    except InvalidReservationError:
        pass
    else:
        raise AssertionError('cancelled reservation reopened')
    assert get_available(path, 'A') == 4
    for quantity in (True, False, 0, -1, 1.5, '1'):
        try:
            reserve(path, 'invalid-' + str(quantity), 'A', quantity)
        except InvalidReservationError:
            pass
        else:
