    for reservation_id in ('', '  ', ' padded '):
        try:
            reserve(path, reservation_id, 'A', 1)
        except InvalidReservationError:
            pass
        else:
            raise AssertionError(f'invalid ID accepted: {reservation_id!r}')
print('focused reservation checks passed')
